import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In R^{d}, let O_d be the regular cross-polytope whose vertices are the 2d points ±e_i for 1 ≤ i ≤ d. Let H_d be the axis-aligned hypercube whose vertices are the centroids of all (d−1)-dimensional facets of O_d, uniformly dilated by a factor {scale_factor} about the origin. If the ratio of the d-dimensional volume of O_d to that of H_d is p/q in lowest terms, find p+q. Here d = {dimension}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a dimension >= 4 to increase difficulty over the 3D seed
d = rng.randint(4, 9)
# Choose a nontrivial dilation factor
s = rng.randint(2, 12)
# Return assignment dictionary
return {'dimension': d, 'scale_factor': s}

    def verifier(assign):
# Check required keys
if 'dimension' not in assign or 'scale_factor' not in assign:
    # Missing assignment keys
    return (False, None)  # missing keys
d = assign['dimension']
s = assign['scale_factor']
# Validate types and domains
if not isinstance(d, int) or not isinstance(s, int):
    return (False, None)  # non-integer inputs
if d < 4:
    return (False, None)  # enforce harder-than-seed: dimension must be >= 4
if s < 2:
    return (False, None)  # ensure nontrivial dilation
# Compute the ratio of volumes.
# For the standard cross-polytope O_d = conv(±e_i), its volume is 2^d / d!.
# The facet centroids are at the 2^d points with coordinates ±1/d, forming a hypercube of side 2/d.
# After uniform dilation by factor s, H_d has side length 2s/d and volume (2s/d)^d.
# Therefore, the ratio V(O_d)/V(H_d) = (2**d / d!) / ((2*s/d)**d) = d^d / (d! * s^d).
import math
num = d ** d
den = math.factorial(d) * (s ** d)
g = math.gcd(num, den)
num //= g
den //= g
answer = num + den
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
